const body = $input.first().json.body || {};
const mode = body.mode === 'urgent' ? 'urgent' : body.mode === 'all' ? 'all' : 'search';
const lat = Number(body.lat), lng = Number(body.lng);
const hasPos = isFinite(lat) && isFinite(lng) && body.lat != null && body.lng != null && Math.abs(lat) <= 90 && Math.abs(lng) <= 180;
if (mode !== 'all' && !hasPos) return [{ json: { ok: false, error: 'invalid lat/lng' } }];

const rad = x => x * Math.PI / 180;
const dist = (a, b, c, d) => {
  const h = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
};
const classify = t => {
  const n = [t.name, t['name:en'], t.description].filter(Boolean).join(' ');
  if (/rabies|animal bite|abtc|anti-?rabies/i.test(n) || t['healthcare:speciality'] === 'animal_bite') return 'rabies';
  if (t.healthcare === 'birth_centre' || /lying[- ]?in|maternity|paanakan|birthing|midwi/i.test(n)) return 'birth';
  if (t.amenity === 'hospital' || t.healthcare === 'hospital') return 'hospital';
  return 'clinic';
};

// ---- 1. Load ALL Caloocan facilities (cached 24h in workflow static data) ----
const store = $getWorkflowStaticData('global');
const TTL = 24 * 3600 * 1000;
let cacheState = 'hit';
if (!store.places || !store.at || Date.now() - store.at > TTL || body.refresh === true) {
  const bbox = '14.60,120.93,14.78,121.09';   // all of Caloocan (North + South)
  const query = `[out:json][timeout:60];(
    nwr(${bbox})[amenity~"^(hospital|clinic|doctors)$"];
    nwr(${bbox})[healthcare~"^(hospital|clinic|birth_centre|doctor)$"];
    nwr(${bbox})[name~"rabies|animal bite|lying|maternity|paanakan|birthing",i];
  );out center tags;`;
  const mirrors = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter', 'https://overpass.private.coffee/api/interpreter'];
  let elements = null, lastErr = '';
  for (let round = 0; round < 2 && !elements; round++) {
    for (const url of mirrors) {
      try {
        const r = await this.helpers.httpRequest({
          method: 'POST', url, json: true, timeout: 70000,
          headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': 'caloocan-health-finder/1.0 (khent.agustin@247ga.co)' },
          body: 'data=' + encodeURIComponent(query),
        });
        if (r && Array.isArray(r.elements) && r.elements.length > 0 && !r.remark) { elements = r.elements; break; }
        lastErr = 'empty/remark: ' + (r && r.remark);
      } catch (e) { lastErr = String(e.message || e); }
    }
  }
  if (!elements) {
    if (store.places) cacheState = 'stale';          // serve old data rather than fail
    else return [{ json: { ok: false, error: 'map data unavailable', detail: lastErr } }];
  } else {
    let list = [];
    for (const e of elements) {
      const t = e.tags || {};
      const la = e.lat ?? (e.center && e.center.lat), lo = e.lon ?? (e.center && e.center.lon);
      const name = t.name || t['name:en'];
      if (la == null || !name) continue;
      const type = classify(t);
      list.push({
        id: e.type + e.id, name, type, lat: la, lng: lo,
        emergency: type === 'hospital' && t.emergency !== 'no',
        phone: (t.phone || t['contact:phone'] || '').split(';')[0].trim(),
        website: t.website || t['contact:website'] || '',
        hours: t.opening_hours || '',
        address: [t['addr:housenumber'], t['addr:street'], t['addr:suburb'] || t['addr:barangay']].filter(Boolean).join(' '),
      });
    }
    // dedupe: same name within 120 m
    const kept = [];
    for (const p of list) {
      if (!kept.find(k => k.name.toLowerCase() === p.name.toLowerCase() && dist(k.lat, k.lng, p.lat, p.lng) < 120)) kept.push(p);
    }
    store.places = kept; store.at = Date.now(); cacheState = 'refreshed';
  }
}
const all = store.places;
const counts = all.reduce((m, p) => (m[p.type] = (m[p.type] || 0) + 1, m), {});
const meta = { cache: cacheState, cachedAt: new Date(store.at).toISOString(), total: all.length, counts };

if (mode === 'all') return [{ json: { ok: true, mode, ...meta, places: all } }];

// ---- 2. Distance / ETA from the user ----
const withDist = all.map(p => {
  const d = dist(lat, lng, p.lat, p.lng);
  return { ...p, distance_m: Math.round(d), eta_min: Math.max(1, Math.round((d * 1.35) / 333)) };  // ~20 km/h city traffic
}).sort((a, b) => a.distance_m - b.distance_m);

if (mode === 'urgent') {
  const hospitals = withDist.filter(p => p.type === 'hospital');
  const best = hospitals[0] || null;
  const dir = p => `https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}`;
  const message = best
    ? `🚨 URGENT — Caloocan Health Finder\nUser: https://www.google.com/maps?q=${lat},${lng}${body.approximate ? ' (approximate)' : ''}\nNearest hospital: ${best.name} (${best.distance_m} m, ~${best.eta_min} min)\nPhone: ${best.phone || 'n/a'}\nDirections: ${dir(best)}\nTime: ${new Date().toISOString()}`
    : `🚨 URGENT — no hospital found near ${lat},${lng}. Advise calling 911.`;
  return [{ json: { ok: true, mode, ...meta, nearest: best && { ...best, directions: dir(best) }, alternatives: hospitals.slice(1, 4), message } }];
}
const radius = Math.min(Math.max(Number(body.radius) || 3000, 500), 20000);
const type = body.type && body.type !== 'all' ? body.type : null;
const places = withDist.filter(p => p.distance_m <= radius && (!type || p.type === type));
return [{ json: { ok: true, mode, radius, ...meta, count: places.length, places } }];
